custom_css:
/*【月光海·玻璃】宁宁 × Claude 自制
  素材：Ttsningning/orange-shop-assets 仓库 theme/moonsea 文件夹
  结构参考了易碎蝶老师的拼接气泡思路，代码为重新编写
  ⭕ 想调位置、颜色、文字，只改下面 :root 里的变量就行 */

@import url("https://cdn.jsdelivr.net/npm/lxgw-wenkai-screen-webfont/style.css");

/* ================= 变量调试处 ================= */
:root {
    --输入框文字: "月光落在海面上……";
    --加载更多文字: "";
    --气泡宽: min(96cqw, 600px);    /* 气泡宽度，手机端约等于全屏 */
    --楼层间距: 26px;               /* 两条消息之间的空隙 */
    --拼接缝: 3px;                   /* 头部/正文/尾部三张卡片之间的缝 */
    --正文字色: #2b3a6e;
    --名字颜色: #ffffff;
    --信息颜色: #e6ecff;             /* 楼层号、计时、字数 */
    --强调蓝: #4d67bf;
    --浅线: #b9c6f0;
    --面板底色: rgba(238, 242, 253, .97);
    --字体: "LXGW WenKai Screen", "LXGW WenKai", "PingFang SC", "Microsoft YaHei", sans-serif;

    /* 以下由宽度自动换算，一般不用动 */
    --头高: calc(var(--气泡宽) * 0.2459);
    --尾高: calc(var(--气泡宽) * 0.1407);
}

body {
    font-family: var(--字体);
}

/* ================= 聊天区 ================= */
#chat {
    container-type: inline-size;
    padding-left: 0 !important;
    padding-right: 0 !important;
    scrollbar-width: none;
}
#chat::-webkit-scrollbar { display: none; }

/* ---------- 气泡正文：九宫格拉伸，多长都不会断 ---------- */
#chat .mes {
    display: block !important;
    box-sizing: border-box;
    width: var(--气泡宽) !important;
    max-width: none !important;
    margin: calc(var(--头高) + var(--拼接缝) + var(--楼层间距)) auto calc(var(--尾高) + var(--拼接缝)) !important;
    padding: calc(var(--气泡宽) * 0.06) calc(var(--气泡宽) * 0.075) calc(var(--气泡宽) * 0.055) !important;
    min-height: calc(var(--气泡宽) * 0.2);
    position: relative;
    overflow: visible !important;
    background: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    border: 0 solid transparent !important;
    border-image-source: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/bubble_mid.png") !important;
    border-image-slice: 52 60 52 60 fill !important;
    border-image-width: calc(var(--气泡宽) * 0.0767) calc(var(--气泡宽) * 0.0885) !important;
    border-image-repeat: stretch !important;
    color: var(--正文字色);
}
#chat .mes:first-of-type { margin-top: calc(var(--头高) + var(--拼接缝) + 12px) !important; }

/* 头部卡片（头像圈 + 名字牌 + 夜海） */
#chat .mes::before,
#chat .mes::after {
    content: "";
    position: absolute;
    left: 0;
    width: 100%;
    background-repeat: no-repeat;
    background-size: 100% 100%;
    pointer-events: none;
}
#chat .mes::before {
    bottom: calc(100% + var(--拼接缝));
    height: var(--头高);
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/bubble_top.png");
}
/* 尾部卡片（星星挂饰的海面） */
#chat .mes::after {
    top: calc(100% + var(--拼接缝));
    height: var(--尾高);
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/bubble_bot.png");
}

/* ---------- 头像：放进头部卡片的圆框里 ---------- */
#chat .mes .mesAvatarWrapper {
    position: absolute !important;
    left: 0;
    bottom: calc(100% + var(--拼接缝));
    top: auto !important;
    width: 100%;
    height: var(--头高);
    margin: 0 !important;
    padding: 0 !important;
    display: block !important;
    pointer-events: none;
    z-index: 2;
}
#chat .mes .mesAvatarWrapper .avatar {
    position: absolute !important;
    left: 7.6%;
    top: 11.5%;
    width: 15.2% !important;
    height: auto !important;
    aspect-ratio: 1;
    margin: 0 !important;
    border-radius: 50% !important;
    overflow: hidden;
    pointer-events: auto;
    box-shadow: 0 0 0 2px rgba(255, 255, 255, .55), 0 0 10px rgba(150, 175, 255, .8);
}
#chat .mes .mesAvatarWrapper .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
    border-radius: 50% !important;
    border: 0 !important;
    box-shadow: none !important;
}

/* ---------- 楼层号 / 计时 / 字数：写在头部的夜空上 ---------- */
#chat .mes .mesIDDisplay,
#chat .mes .mes_timer,
#chat .mes .tokenCounterDisplay {
    position: absolute !important;
    top: 49%;
    margin: 0 !important;
    padding: 0 !important;
    font-size: calc(var(--气泡宽) * 0.027) !important;
    line-height: 1;
    color: var(--信息颜色) !important;
    opacity: .95 !important;
    white-space: nowrap;
    text-shadow: 0 0 4px rgba(70, 100, 200, .9);
}
#chat .mes .mesIDDisplay { left: 47.5%; }
#chat .mes .mes_timer { left: 55%; }
#chat .mes .tokenCounterDisplay { left: 64.5%; }

/* ---------- 名字：放进名字牌 ---------- */
#chat .mes .mes_block {
    position: static !important;
    margin: 0 !important;
    padding: 0 !important;
    width: 100%;
}
#chat .mes .ch_name {
    position: absolute !important;
    left: 0;
    bottom: calc(100% + var(--拼接缝));
    width: 100%;
    height: var(--头高);
    display: block !important;
    z-index: 3;
    pointer-events: none;
}
#chat .mes .ch_name .name_text {
    position: absolute;
    left: 25%;
    top: 18.5%;
    width: 18.6%;
    height: 27%;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    white-space: nowrap;
    font-size: calc(var(--气泡宽) * 0.034);
    font-weight: 600;
    letter-spacing: 1px;
    color: var(--名字颜色);
    text-shadow: 0 0 6px rgba(110, 140, 230, 1), 0 1px 2px rgba(25, 35, 90, .7);
    pointer-events: auto;
}
#chat .mes .timestamp {
    position: absolute;
    left: 47.5%;
    top: 68%;
    font-size: calc(var(--气泡宽) * 0.024);
    color: var(--信息颜色) !important;
    text-shadow: 0 0 4px rgba(70, 100, 200, .9);
    white-space: nowrap;
}
#chat .mes .mes_ghost {
    position: absolute;
    left: 44.5%;
    top: 26%;
    color: #fff;
}

/* ---------- 编辑按钮：头部右上 ---------- */
#chat .mes .mes_buttons,
#chat .mes .mes_edit_buttons {
    position: absolute !important;
    right: 4.5%;
    top: 40%;
    margin: 0 !important;
    padding: 0 !important;
    align-items: center;
    gap: 4px;
    pointer-events: auto;
    filter: none !important;
}
#chat .mes .mes_buttons { display: flex; }
#chat .mes .mes_buttons .mes_button,
#chat .mes .mes_buttons .extraMesButtons > div {
    opacity: 1 !important;
    filter: none !important;
    color: #fff !important;
    text-shadow: 0 0 4px rgba(70, 100, 200, .9);
}
#chat .mes .extraMesButtons {
    background: rgba(70, 95, 180, .55);
    border-radius: 999px;
    padding: 2px 6px;
}
#chat .mes .mes_edit_buttons .menu_button {
    width: 26px;
    height: 26px;
    padding: 0 !important;
    margin: 0 !important;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
}

/* ---------- 翻页箭头 + 计数：尾部卡片上 ---------- */
#chat .mes .swipe_left,
#chat .mes .swipeRightBlock {
    position: absolute !important;
    top: calc(100% + var(--拼接缝) + var(--尾高) * 0.2) !important;
    bottom: auto !important;
    z-index: 5;
    margin: 0 !important;
}
#chat .mes .swipe_left { left: 3.5% !important; right: auto !important; }
#chat .mes .swipeRightBlock {
    right: 3.5% !important;
    left: auto !important;
    display: flex;
    flex-direction: row-reverse !important;
    align-items: center;
    gap: 6px;
}
#chat .mes .swipes-counter {
    position: static !important;
    margin: 0 !important;
    font-size: 11px;
    color: #fff !important;
    opacity: 1 !important;
    text-shadow: 0 0 4px rgba(70, 100, 200, 1);
}

/* ---------- 正文排版 ---------- */
#chat .mes .mes_text {
    padding: 0 !important;
    color: var(--正文字色);
    line-height: 1.85;
    letter-spacing: .02em;
    text-align: justify;
    overflow-wrap: anywhere;
}
#chat .mes .mes_text em,
#chat .mes .mes_text i { color: var(--SmartThemeEmColor); }
#chat .mes .mes_text q {
    color: var(--SmartThemeQuoteColor);
    background: linear-gradient(transparent 62%, rgba(150, 175, 245, .35) 62%);
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
}
#chat .mes .mes_text strong { color: #263f96; }
.mes_text blockquote,
.mes_reasoning blockquote {
    border-left: 3px solid #9fb2ee !important;
    background: rgba(255, 255, 255, .45) !important;
    border-radius: 0 10px 10px 0;
    padding: 4px 10px !important;
    margin: 6px 0;
}
.mes_text code,
.mes_text pre {
    background: rgba(255, 255, 255, .6) !important;
    border: 1px solid var(--浅线) !important;
    border-radius: 8px;
    color: var(--正文字色) !important;
}
::selection { background: rgba(77, 103, 191, .85); color: #fff; }

/* 分割线 --- ：两道细线夹一颗星 */
.mes_text hr {
    all: unset;
    display: block;
    height: 22px;
    margin: 10px 0;
    background:
        url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/deco_star1.png") center / auto 100% no-repeat,
        linear-gradient(90deg, transparent, #9fb2ee 15%, #9fb2ee 43%, transparent 46%, transparent 54%, #9fb2ee 57%, #9fb2ee 85%, transparent) center / 100% 1.5px no-repeat;
}

/* ---------- 思维链 ---------- */
#chat .mes .mes_reasoning_details {
    margin: 0 0 12px !important;
    padding: 6px 10px !important;
    background: rgba(255, 255, 255, .42);
    border: 1px solid rgba(140, 160, 225, .45);
    border-radius: 14px;
}
#chat .mes .mes_reasoning_header {
    background: none !important;
    color: var(--强调蓝) !important;
    padding-left: 26px !important;
    position: relative;
}
#chat .mes .mes_reasoning_header::before {
    content: "";
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
    width: 22px;
    height: 18px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/deco_sparkles.png") center / contain no-repeat;
}
#chat .mes .mes_reasoning {
    color: #5c6aa0 !important;
    border-left: 2px solid var(--浅线) !important;
    padding-left: 8px !important;
}

/* ---------- 编辑框 ---------- */
#chat .mes .edit_textarea {
    background: rgba(255, 255, 255, .8) !important;
    border: 1px solid var(--浅线) !important;
    border-radius: 12px !important;
    color: var(--正文字色) !important;
}

/* 加载更多消息 */
#show_more_messages {
    width: 168px;
    height: 42px;
    margin: 24px auto 0 !important;
    padding: 0 !important;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/btn_loadmore.png") center / contain no-repeat !important;
    border: 0 !important;
    box-shadow: none !important;
    color: transparent !important;
    font-size: 0 !important;
}

/* ================= 顶栏 ================= */
#top-bar {
    background: none !important;
    box-shadow: none !important;
    border: 0 solid transparent !important;
    border-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/topbar.png") 52 64 52 64 fill / 19px 24px !important;
    backdrop-filter: none !important;
}
.drawer-icon.fa-fw::before,
.drawer-icon.fa-fw::after { content: "" !important; }
.drawer-icon.fa-fw {
    width: 30px !important;
    height: 30px !important;
    font-size: 0 !important;
    background: center / contain no-repeat;
    opacity: 1 !important;
    filter: drop-shadow(0 0 3px rgba(190, 210, 255, .8));
    transition: transform .25s ease;
}
.drawer-icon.fa-fw.openIcon { transform: translateY(2px) scale(1.08); }
#ai-config-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_brain.png"); }
#sys-settings-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_chat.png"); }
#advanced-formatting-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_pencil.png"); }
#WI-SP-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_book.png"); }
#user-settings-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_gear.png"); }
#backgrounds-drawer-toggle .drawer-icon,
#logo_block .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/tile_sea1.png"); }
#extensions-settings-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/btn_plus.png"); }
#persona-management-button .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_star_on.png"); }
#rightNavHolder .drawer-icon { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/tile_sea2.png"); }

/* ================= 图标替换 ================= */
.mes .swipe_left::before,
.mes .swipe_right::before,
.mes_button.extraMesButtonsHint::before,
.mes_button.mes_edit::before,
.mes_edit_done::before,
.mes_edit_cancel::before,
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#mes_stop .fa-circle-stop::before,
.inline-drawer-icon::before,
#favorite_button::before,
#load-spinner::before,
#load-spinner::after {
    content: none !important;
    display: none !important;
}

.mes .swipe_left,
.mes .swipe_right {
    width: 26px !important;
    height: 26px !important;
    font-size: 0 !important;
    background: center / contain no-repeat !important;
    opacity: 1 !important;
    filter: drop-shadow(0 0 3px rgba(70, 100, 200, .6));
}
.mes .swipe_left { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_left.png") !important; }
.mes .swipe_right { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_right.png") !important; }

.mes_button.extraMesButtonsHint,
.mes_button.mes_edit {
    width: 26px !important;
    height: 22px !important;
    font-size: 0 !important;
    padding: 0 !important;
    background: center / contain no-repeat !important;
}
.mes_button.extraMesButtonsHint { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_more.png") !important; }
.mes_button.mes_edit { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_pencil.png") !important; }

.mes_edit_done.menu_button,
.mes_edit_cancel.menu_button {
    font-size: 0 !important;
    background: center / contain no-repeat !important;
    border: 0 !important;
    box-shadow: none !important;
}
.mes_edit_done.menu_button { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_check.png") !important; }
.mes_edit_cancel.menu_button { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_close.png") !important; }

#options_button,
#extensionsMenuButton,
#send_but,
#mes_stop .fa-circle-stop {
    width: 36px !important;
    height: 36px !important;
    font-size: 0 !important;
    background: center / 32px auto no-repeat !important;
    opacity: 1 !important;
}
#options_button { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/btn_menu.png") !important; }
#extensionsMenuButton { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/btn_plus.png") !important; }
#send_but { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/btn_send.png") !important; }
#mes_stop .fa-circle-stop { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/btn_stop.png") !important; }

.inline-drawer-icon {
    width: 22px !important;
    height: 18px !important;
    font-size: 0 !important;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_down.png") center / contain no-repeat !important;
    transition: transform .25s ease;
}
.inline-drawer-icon.up { transform: rotate(180deg); }

#favorite_button {
    width: 26px;
    height: 24px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_star.png") center / contain no-repeat !important;
}
#favorite_button.fav_on { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_star_on.png") !important; }

#load-spinner {
    width: 64px;
    height: 64px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/spinner.png") center / contain no-repeat;
    animation: ms-spin 1.4s linear infinite;
}
@keyframes ms-spin { to { transform: rotate(360deg); } }

/* ================= 输入框 ================= */
#form_sheld { background: transparent !important; }
#send_form {
    position: relative;
    min-height: 54px;
    padding: 4px 14px !important;
    background: none !important;
    box-shadow: none !important;
    border: 0 solid transparent !important;
    border-radius: 0 !important;
    border-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/input_bar.png") 40 56 40 56 fill / 24px 32px !important;
    backdrop-filter: none !important;
    overflow: visible !important;
}
#send_form::before {
    content: "";
    position: absolute;
    right: 64px;
    top: -34px;
    width: 46px;
    height: 36px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/deco_sailboat.png") center / contain no-repeat;
    pointer-events: none;
    animation: ms-bob 3.6s ease-in-out infinite;
    z-index: 2;
}
@keyframes ms-bob {
    0%, 100% { transform: translateY(0) rotate(-2deg); }
    50% { transform: translateY(-3px) rotate(2deg); }
}
#send_form:has(#send_textarea:focus-visible) { outline: none; }
#send_textarea {
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
    color: var(--正文字色) !important;
    resize: none;
}
#send_textarea::placeholder { color: transparent !important; }
#nonQRFormItems { position: relative; }
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--输入框文字);
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    font-size: 14px;
    color: #7385c4;
    white-space: nowrap;
    pointer-events: none;
    letter-spacing: 2px;
    z-index: 1;
}

/* ================= 面板 & 设置页 ================= */
.drawer-content,
#right-nav-panel,
#left-nav-panel,
#floatingPrompt,
#cfgConfig {
    background: linear-gradient(180deg, rgba(200, 212, 250, .97), var(--面板底色) 140px) !important;
    border: 1.5px solid #c9d4f7 !important;
    border-radius: 18px !important;
    box-shadow: inset 0 0 0 3px rgba(255, 255, 255, .55), 0 10px 28px rgba(45, 65, 150, .28) !important;
    backdrop-filter: none !important;
}

.standoutHeader,
#user-settings-block h4,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
    position: relative;
    background: linear-gradient(180deg, #7790de, #4e68bd) !important;
    color: #fff !important;
    border: 1px solid rgba(255, 255, 255, .75) !important;
    border-radius: 999px !important;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, .55), 0 2px 6px rgba(55, 75, 160, .3) !important;
    padding: 6px 14px 6px 34px !important;
}
.standoutHeader > *,
#user-settings-block h4 > *,
#extensions_settings .inline-drawer-header > *,
#extensions_settings2 .inline-drawer-header > * { color: #fff !important; }
.standoutHeader::before,
#user-settings-block h4::before,
#extensions_settings .inline-drawer-toggle.inline-drawer-header::before,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header::before {
    content: "";
    position: absolute;
    left: 9px;
    top: 50%;
    transform: translateY(-50%);
    width: 18px;
    height: 20px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/deco_star2.png") center / contain no-repeat;
}

.menu_button {
    background: linear-gradient(180deg, #ffffff, #e0e7fb) !important;
    color: var(--正文字色) !important;
    border: 1px solid #b6c4f0 !important;
    border-radius: 999px !important;
    box-shadow: inset 0 1px 0 #fff, 0 2px 4px rgba(60, 80, 160, .18) !important;
    filter: none !important;
}
.menu_button:hover { background: linear-gradient(180deg, #ffffff, #cfdafa) !important; }

.text_pole,
textarea:not(#send_textarea),
select,
input:not([type="checkbox"], [type="radio"], [type="range"], [type="file"], [type="image"], [type="color"]) {
    background: rgba(255, 255, 255, .85) !important;
    border: 1px solid #c3cef3 !important;
    border-radius: 10px !important;
    color: var(--正文字色) !important;
    box-shadow: inset 0 1px 3px rgba(60, 80, 160, .12) !important;
}

input[type="checkbox"] {
    background-color: #fff !important;
    border: 1.5px solid #9fb0e6 !important;
    border-radius: 5px !important;
    box-shadow: none !important;
}
input[type="checkbox"]:checked { background-color: #5a74c9 !important; }

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 22px;
    height: 24px;
    border: 0;
    border-radius: 0;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/deco_star1.png") center / contain no-repeat;
    box-shadow: none;
}
.neo-range-slider {
    height: 4px !important;
    background: #c9d3f5 !important;
    border-radius: 999px !important;
    box-shadow: none !important;
}

/* 预设列表 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    background: rgba(255, 255, 255, .75) !important;
    border: 1px solid #c9d4f7 !important;
    border-radius: 12px !important;
    margin-bottom: 6px;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled {
    background: rgba(225, 231, 250, .6) !important;
    opacity: .75;
}

/* 角色列表 & 头像 */
.character_select,
.bogus_folder_select,
.avatar-container {
    border-radius: 14px !important;
    background: rgba(255, 255, 255, .55) !important;
    border: 1px solid #d0daf8 !important;
    margin-top: 6px;
}
.character_select.is_fav .avatar { outline: none !important; }
.character_select .avatar img,
.avatar-container .avatar img,
#quickPersonaImg {
    border-radius: 50% !important;
    border: 2px solid #fff !important;
    box-shadow: 0 0 0 1.5px #9fb2ee, 0 0 8px rgba(150, 175, 255, .6) !important;
}
.world_set,
.toggleEnabled,
.fav_on { color: var(--强调蓝) !important; }
.tag {
    background: #e3e9fc !important;
    color: var(--强调蓝) !important;
    border: 1px solid #c3cef3 !important;
    border-radius: 999px !important;
}

/* 弹窗、菜单 */
#options,
#extensionsMenu,
.popup,
.list-group,
#select_chat_popup {
    background: var(--面板底色) !important;
    border: 1.5px solid #c9d4f7 !important;
    border-radius: 16px !important;
    box-shadow: 0 10px 28px rgba(45, 65, 150, .28) !important;
    color: var(--正文字色) !important;
}

/* 通知 */
#toast-container > .toast {
    background: var(--面板底色) !important;
    border: 1.5px solid #c9d4f7 !important;
    border-radius: 16px !important;
    box-shadow: 0 6px 20px rgba(45, 65, 150, .3) !important;
    padding: 10px 14px 10px 48px !important;
    opacity: 1 !important;
    position: relative;
}
#toast-container > .toast::before {
    content: "";
    position: absolute;
    left: 10px;
    top: 50%;
    transform: translateY(-50%);
    width: 30px;
    height: 30px;
    background: center / contain no-repeat;
}
#toast-container > .toast-success::before,
#toast-container > .toast-info::before { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_check.png"); }
#toast-container > .toast-error::before,
#toast-container > .toast-warning::before { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/orange-shop-assets@main/theme/moonsea/ico_close.png"); }
.toast-title,
.toast-message { color: var(--正文字色) !important; }

/* 隐藏快捷回复，点输入框时再出现 */
.qr--buttons {
    max-height: 0;
    opacity: 0;
    overflow: hidden;
    transition: max-height .4s ease, opacity .3s ease;
}
#send_form:focus-within .qr--buttons {
    max-height: 120px;
    opacity: 1;
}

::-webkit-scrollbar { width: 4px; height: 4px; }
::-webkit-scrollbar-thumb { background: #a9b8ea; border-radius: 4px; }
